{"tool_call_id": "exec-f808c80c-d8c4-4594-99c6-ada1e05cc42b", "title": "python - <<'PY'
import sys
from label_tools import normalize_label
whitespace = [chr(n) for n in range(sys.maxunicode + 1) if chr(n).isspace()]
for w in whitespace:
    assert normalize_label(w + 'Core' + w * 2 + 'Switch' + w) == 'core_switch'
    try:
        normalize_label(w * 3)
    except ValueError:
        pass
    else:
        raise AssertionError(repr(w))
for label in ['Core-Switch', ' A_B.C:/D-1! (E) ', 'İ Σ Straße', 'already_normalized', '-_.!']:
    result = normalize_label(label)
    assert normalize_label(result) == result
print(f'Independent boundary checks passed for all {len(whitespace)} Python Unicode whitespace characters; five idempotence checks passed.')
